import {canvas} from './renderer.js';
import {clone} from './model.js';
import {downloadBlob} from './storage.js';
import {alphaCanvas} from './cutout-workflow.js';
import {assertProductSource} from './product-workflow.js';
import {captureLandscape,applyLandscape} from './landscape-workflow.js';
import {createProductClient} from './product-client.js';
import {createEditHistory,bindEditorHistory} from './edit-history.js';
import {LANDSCAPE_FIELDS,LANDSCAPE_DEFAULTS,LANDSCAPE_PRESETS,autoLandscapeParams,landscapeSkyMask} from './landscape-engine.js';

const $=s=>document.querySelector(s),clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const slider=(key,params)=>{const [name,min,max,step,unit]=LANDSCAPE_FIELDS[key];return `<label class='product-slider'><span>${name}</span><output id='landscape-value-${key}'>${params[key]}${unit}</output><input data-landscape-param='${key}' type='range' min='${min}' max='${max}' step='${step}' value='${params[key]}' aria-label='${name}'></label>`;};
function pixels(c){return c.getContext('2d',{willReadFrequently:true}).getImageData(0,0,c.width,c.height).data;}
function imageCanvas(data,w,h){const c=canvas(w,h),x=c.getContext('2d'),p=x.createImageData(w,h);p.data.set(data);x.putImageData(p,0,0);return c;}
export function createLandscapeStudio(api,{processorFactory=()=>createProductClient('./landscape-worker.js','phong cảnh')}={}){
 let active=null;
 function cancel(){if(active){active.close();api.closeModal(true);}}
 async function open(initialPreset='sunset'){
  cancel();const doc=api.doc(),target=['image','paint'].includes(api.layer?.()?.type)?api.layer():doc?.layers.filter(l=>['image','paint'].includes(l.type)&&l.visible).sort((a,b)=>b.width*b.height-a.width*a.height)[0];
  if(!target){api.showModal('Phong cảnh HDR','Sáng rõ · trời trong · chiều ấm',`<div class='product-empty'><span>LANDSCAPE STUDIO</span><h3>Giữ sắc trời.<br>Mở tầng sáng.</h3><p>Mở ảnh phong cảnh để tự cân vùng sáng tối, tăng nét và thử sắc chiều nhẹ. Mẫu có sẵn là minh họa đồ họa.</p></div>`,[{label:'Đóng',run:()=>api.closeModal()},{label:'Thử ảnh mẫu',run:()=>{api.closeModal();api.runAction('landscape-sample');}},{label:'Mở ảnh',primary:true,run:()=>{api.closeModal();api.runAction('open');}}]);return;}
  const snapshot=captureLandscape(doc,target),saved=target.landscapeRecipe?clone(target.landscapeRecipe):null,source=saved?.source||target.source,image=api.assets.get(source)||await api.assets.load(source),w=image.width,h=image.height;
  if(!w||!h)throw Error('Ảnh phong cảnh không hợp lệ.');
  const original=canvas(w,h);original.getContext('2d').drawImage(image,0,0);const raw=pixels(original);let baseSky=null;
  if(saved?.skySource){const im=await api.assets.load(saved.skySource);if(im.width!==w||im.height!==h)throw Error('Mask trời đã lưu không khớp ảnh nguồn.');const c=canvas(w,h);c.getContext('2d').drawImage(im,0,0);const d=pixels(c);baseSky=Float32Array.from({length:w*h},(_,i)=>d[i*4+3]/255);}
  let mounted=true,busy=false,ready=false,sequence=0,revision=0,renderedRevision=-1,skyVersion=0,preparedSky=-1,timer=null,preset=saved?.preset||initialPreset,params={...LANDSCAPE_DEFAULTS,...saved?.params},strokes=clone(saved?.strokes||[]),analysis=null,result=null,rendered=null,mask=null,overlay=null,autoPending=!saved,split=0,zoom=1,center=[.5,.5],showSky=false,tool='pan',brush=.024,drawing=null,pan=null,unbind=()=>{};
  const processor=processorFactory(),journal=createEditHistory({strip:s=>({...s,result:null})}),valid=token=>mounted&&sequence===token;
  const state={close(){if(!mounted)return;mounted=false;sequence++;revision++;clearTimeout(timer);processor.stop();unbind();journal.clear();if(active===state)active=null;},getState:()=>({busy,result,params:clone(params),preset,baseSky,mask,strokes:clone(strokes),analysis,center:clone(center),zoom,history:journal.stats()})};active=state;
  const snap=()=>({params:clone(params),preset,baseSky,strokes:clone(strokes),result});
  function note(message,error=false){if(mounted){$('#landscape-status').textContent=message;$('#landscape-status').classList.toggle('is-error',error);}}
  function sync(){if(!mounted)return;for(const el of document.querySelectorAll('[data-landscape-param]')){const key=el.dataset.landscapeParam;el.value=params[key];$('#landscape-value-'+key).textContent=params[key]+LANDSCAPE_FIELDS[key][4];}
   for(const el of document.querySelectorAll('[data-landscape-preset]')){const on=el.dataset.landscapePreset===preset;el.classList.toggle('active',on);el.setAttribute('aria-pressed',String(on));}
   for(const el of document.querySelectorAll('[data-landscape-tool]')){el.classList.toggle('active',el.dataset.landscapeTool===tool);el.disabled=busy;}
   $('#landscape-undo').disabled=!journal.canUndo();$('#landscape-redo').disabled=!journal.canRedo();$('#landscape-stop').hidden=!busy;$('#landscape-apply').disabled=$('#landscape-export').disabled=busy||!result||renderedRevision!==revision;$('#landscape-auto-sky').disabled=busy;$('#landscape-show-sky').checked=showSky;$('#landscape-sky-enabled').checked=params.skyEnabled;$('#landscape-preview').setAttribute('aria-busy',String(busy));$('#landscape-preview').style.cursor=tool==='pan'?'grab':'crosshair';
   $('#landscape-analysis').textContent=analysis?`Đã phân tích ảnh · gợi ý trời ${Math.round(analysis.skyFraction*100)}% · ${w.toLocaleString('vi-VN')} × ${h.toLocaleString('vi-VN')} px`:`${w.toLocaleString('vi-VN')} × ${h.toLocaleString('vi-VN')} px · đang đọc vùng sáng tối`;
   $('#landscape-sky-note').textContent=!params.skyEnabled?'Đã tắt chỉnh trời / mây riêng; cân sáng HDR toàn ảnh vẫn hoạt động.':analysis&&analysis.skyFraction<.01?'Chưa tìm được vùng trời rõ. Dùng cọ Thêm trời hoặc tắt chỉnh trời riêng.':'Vùng trời được gợi ý theo màu và kết nối từ phía trên ảnh. Bật xem vùng để kiểm tra quanh cây, mái nhà và đường chân trời.';
  }
  function recalc(){if(!baseSky){mask=overlay=null;return;}mask=landscapeSkyMask(baseSky,w,h,strokes);if(showSky){const d=new Uint8ClampedArray(w*h*4);for(let i=0;i<mask.length;i++)d.set([111,195,239,mask[i]*130],i*4);overlay=imageCanvas(d,w,h);}else overlay=null;}
  function view(){const width=w/zoom,height=h/zoom;return{x:clamp(center[0]*w-width/2,0,w-width),y:clamp(center[1]*h-height/2,0,h-height),width,height};}
  function draw(){if(!mounted)return;const c=$('#landscape-preview'),v=view(),scale=Math.min(4,1500/Math.max(v.width,v.height));c.width=Math.max(1,Math.round(v.width*scale));c.height=Math.max(1,Math.round(v.height*scale));const x=c.getContext('2d');x.drawImage(original,v.x,v.y,v.width,v.height,0,0,c.width,c.height);if(rendered){x.save();x.beginPath();x.rect(c.width*split/100,0,c.width,c.height);x.clip();x.drawImage(rendered,v.x,v.y,v.width,v.height,0,0,c.width,c.height);x.restore();}if(showSky&&overlay)x.drawImage(overlay,v.x,v.y,v.width,v.height,0,0,c.width,c.height);
   if(drawing){x.beginPath();x.strokeStyle=drawing.add?'#a5e5fb':'#f0c4aa';x.lineWidth=drawing.radius*Math.min(w,h)*2*scale;x.lineCap=x.lineJoin='round';drawing.points.forEach(([px,py],i)=>i?x.lineTo((px*w-v.x)*scale,(py*h-v.y)*scale):x.moveTo((px*w-v.x)*scale,(py*h-v.y)*scale));if(drawing.points.length===1){const [px,py]=drawing.points[0];x.lineTo((px*w-v.x)*scale+.1,(py*h-v.y)*scale);}x.stroke();}
   if(tool==='light'){const px=(params.sunX/100*w-v.x)*scale,py=(params.sunY/100*h-v.y)*scale;x.strokeStyle='#efd4a0';x.lineWidth=1.5;x.beginPath();x.arc(px,py,10,0,Math.PI*2);x.moveTo(px-16,py);x.lineTo(px+16,py);x.moveTo(px,py-16);x.lineTo(px,py+16);x.stroke();}
   if(rendered&&split>0&&split<100){x.strokeStyle='#e8f2fa';x.lineWidth=2;x.beginPath();x.moveTo(c.width*split/100,0);x.lineTo(c.width*split/100,c.height);x.stroke();}
  }
  function setResult(value){if(value.width!==w||value.height!==h||value.data?.length!==w*h*4)throw Error('Kết quả không khớp ảnh nguồn.');result=value;rendered=imageCanvas(value.data,w,h);renderedRevision=revision;}
  function schedule(delay=140){clearTimeout(timer);timer=setTimeout(render,delay);}
  function edit(label,key=null,skyChanged=false){revision++;result=null;renderedRevision=-1;if(skyChanged){skyVersion++;recalc();}journal.record(snap(),label,key);sync();draw();schedule();}
  async function render(){clearTimeout(timer);timer=null;if(!mounted||busy)return;const token=sequence,expected=revision,expectedSky=skyVersion,expectedBase=baseSky,expectedStrokes=clone(strokes);busy=true;sync();note('Đang cân tầng sáng, giữ mây và tăng nét có giới hạn…');let failed=false;
   try{assertProductSource(api.doc(),snapshot);if(!ready){const out=await processor.run({kind:'prepare',data:raw,width:w,height:h,baseSky:expectedBase,strokes:expectedStrokes});if(!valid(token))return;analysis=out.analysis;ready=true;preparedSky=expectedSky;if(!baseSky&&skyVersion===expectedSky){baseSky=out.baseSky;recalc();}if(autoPending&&expected===revision){params=autoLandscapeParams(analysis,preset,params);autoPending=false;sync();}}
    if(!valid(token)||expected!==revision)return;
    if(preparedSky!==expectedSky){await processor.run({kind:'sky',baseSky,strokes:expectedStrokes});if(!valid(token)||expected!==revision)return;preparedSky=expectedSky;}
    const out=await processor.run({kind:'render',params:clone(params)});if(!valid(token)||expected!==revision)return;assertProductSource(api.doc(),snapshot);setResult(out);journal.replace(snap());draw();note('Đã cân phong cảnh. Giữ sắc mây chiều và pixel nguồn; kéo so sánh hoặc chỉnh lại theo ý.');
   }catch(e){if(valid(token)&&e.name!=='AbortError'){failed=true;ready=false;preparedSky=-1;note(e.message,true);}}
   finally{if(valid(token)){busy=false;sync();if(!failed&&expected!==revision)schedule(0);}}
  }
  function history(forward=false){const s=forward?journal.redo():journal.undo();if(!s)return;sequence++;revision++;clearTimeout(timer);processor.stop();ready=busy=false;preparedSky=-1;autoPending=false;drawing=pan=null;params=clone(s.params);preset=s.preset;baseSky=s.baseSky;strokes=clone(s.strokes);skyVersion++;result=rendered=null;renderedRevision=-1;recalc();if(s.result)setResult(s.result);else schedule(0);sync();draw();note(forward?'Đã làm lại điều chỉnh.':'Đã hoàn tác. Ctrl+Shift+Z để làm lại.');}
  function choosePreset(id){if(!LANDSCAPE_PRESETS.some(p=>p.id===id))return;preset=id;params=autoLandscapeParams(analysis,preset,{amount:100,skyEnabled:params.skyEnabled});autoPending=!analysis;edit('Kiểu phong cảnh');}
  function recipe(){return{version:1,engine:'landscape-sdr-v1',source,width:w,height:h,preset,params:clone(params),skySource:baseSky?alphaCanvas(baseSky,w,h).toDataURL():null,strokes:clone(strokes)};}
  function apply(){if(busy||!result||renderedRevision!==revision)return;try{applyLandscape(api.doc(),snapshot,rendered,recipe(),api.assets);state.close();api.closeModal();api.commit(saved?'Sửa lại Phong cảnh HDR':'Phong cảnh HDR');api.toast('Đã lưu layer riêng cùng nguồn, vùng trời và thanh chỉnh.');}catch(e){note(e.message,true);}}
  api.showModal('Phong cảnh HDR','Một chạm · trời trong · sắc chiều nhẹ',`<div class='product-studio landscape-studio'><section class='product-image-side'><div class='product-image-heading'><span>LANDSCAPE · GỐC / KẾT QUẢ</span><select id='landscape-zoom' aria-label='Thu phóng phong cảnh'><option value='1'>Toàn ảnh</option><option value='2'>200%</option><option value='4'>400%</option></select><button id='landscape-stop' hidden>Dừng xử lý</button><span class='product-local'>LOCAL · 6.8</span></div><div class='product-canvas-wrap'><canvas id='landscape-preview' aria-label='Xem phong cảnh, sửa vùng trời hoặc chọn tâm ánh ấm'></canvas><span class='product-view-label'>LANDSCAPE STUDIO</span></div><div class='lab-compare'><span>Gốc</span><input id='landscape-split' type='range' min='0' max='100' value='0' aria-label='So sánh phong cảnh HDR'><span>HDR</span></div><div class='product-tools'><button id='landscape-auto' class='landscape-one-click'>HDR chiều nhẹ · 1 chạm</button><button id='landscape-undo'>Hoàn tác · Ctrl Z</button><button id='landscape-redo'>Làm lại · Ctrl Shift Z</button></div><div class='product-tools'><button data-landscape-tool='pan'>Kéo ảnh</button><button data-landscape-tool='add'>Thêm trời</button><button data-landscape-tool='subtract'>Bỏ vùng trời</button><button data-landscape-tool='light'>Chọn tâm nắng</button></div><div class='product-review'><label class='check-row'><input id='landscape-show-sky' type='checkbox'> Xem vùng trời</label><label>Cỡ cọ <input id='landscape-brush' type='range' min='.3' max='15' step='.1' value='2.4' aria-label='Cỡ cọ vùng trời'></label><button id='landscape-auto-sky'>Tìm trời lại</button></div><p id='landscape-status' class='product-status' role='status'></p><p id='landscape-analysis' class='product-fine'></p><p id='landscape-sky-note' class='product-fine'></p></section><aside class='product-controls'><div class='product-intro'><span>LANDSCAPE STUDIO</span><h3>Rõ tầng sáng.<br>Giữ sắc trời.</h3><p>Mở bóng tối, tăng độ trong và màu rực vừa đủ. Giữ mây vàng hồng khi làm trời xanh hơn.</p></div><div class='product-presets'>${LANDSCAPE_PRESETS.map(p=>`<button data-landscape-preset='${p.id}'><strong>${p.name}</strong><small>${p.note}</small></button>`).join('')}</div>${slider('amount',params)}<div class='product-section-title'><span>01</span> TẦNG SÁNG & ĐỘ SÂU</div>${['hdr','shadows','highlights','exposure','contrast'].map(k=>slider(k,params)).join('')}<details class='product-detail-settings'><summary>Độ nét, màu & hạt</summary>${['clarity','sharpness','noise','vibrance','dehaze'].map(k=>slider(k,params)).join('')}</details><div class='product-section-title'><span>02</span> TRỜI XANH & MÂY CHIỀU</div><label class='check-row'><input id='landscape-sky-enabled' type='checkbox' checked> Chỉnh trời / mây theo vùng trời</label>${['skyBlue','skyDetail','warmth','glow'].map(k=>slider(k,params)).join('')}<details class='product-detail-settings'><summary>Vị trí ánh ấm</summary>${['sunX','sunY'].map(k=>slider(k,params)).join('')}<p class='product-fine'>Dời tâm để nhấn sắc ấm đang có. Nắng nhẹ không thay vị trí mặt trời thật hoặc vẽ lại mây.</p></details><div class='product-actions'><button id='landscape-balance'>Tự cân lại</button><button id='landscape-original'>Về ảnh gốc</button></div><p class='product-fine landscape-limit'>Hiệu ứng HDR từ một ảnh, xuất ảnh SDR thông thường. Giữ nguồn gốc; vùng đen/cháy sáng đã mất chi tiết không được khôi phục bằng suy đoán.</p></aside></div>`,[{label:'Hủy',run:()=>api.closeModal(true)},{label:saved?'Cập nhật layer':'Áp thành layer riêng',primary:true,run:apply},{label:'Xuất PNG nguyên độ phân giải',run:async()=>{if(busy||!result||renderedRevision!==revision)return;const blob=await new Promise(resolve=>rendered.toBlob(resolve,'image/png'));if(blob)downloadBlob(blob,'luma-landscape-hdr.png');}}],()=>{
   $('[data-modal-button="1"]').id='landscape-apply';$('[data-modal-button="2"]').id='landscape-export';
   $('#landscape-split').oninput=e=>{split=Number(e.target.value);draw();};$('#landscape-zoom').onchange=e=>{zoom=Number(e.target.value);draw();};$('#landscape-show-sky').onchange=e=>{showSky=e.target.checked;recalc();draw();};$('#landscape-brush').oninput=e=>brush=Number(e.target.value)/100;
   for(const el of document.querySelectorAll('[data-landscape-param]')){const key=el.dataset.landscapeParam;el.oninput=()=>{autoPending=false;params[key]=Number(el.value);edit(LANDSCAPE_FIELDS[key][0],key);};el.onchange=()=>journal.endGroup();}
   for(const el of document.querySelectorAll('[data-landscape-preset]'))el.onclick=()=>choosePreset(el.dataset.landscapePreset);$('#landscape-auto').onclick=()=>choosePreset('sunset');$('#landscape-balance').onclick=()=>choosePreset(preset);
   $('#landscape-sky-enabled').onchange=e=>{autoPending=false;params.skyEnabled=e.target.checked;edit('Bật / tắt chỉnh trời');};$('#landscape-original').onclick=()=>{autoPending=false;params.amount=0;edit('Về ảnh gốc');};$('#landscape-undo').onclick=()=>history();$('#landscape-redo').onclick=()=>history(true);unbind=bindEditorHistory(()=>history(),()=>history(true));
   $('#landscape-stop').onclick=()=>{sequence++;revision++;clearTimeout(timer);timer=null;processor.stop();ready=busy=false;preparedSky=-1;result=null;renderedRevision=-1;sync();note('Đã dừng. Chỉnh thông số hoặc bấm 1 chạm để chạy lại; nguồn vẫn giữ nguyên.');};$('#landscape-auto-sky').onclick=()=>{if(busy)return;baseSky=null;strokes=[];ready=false;preparedSky=-1;edit('Tìm lại vùng trời',null,true);};
   for(const el of document.querySelectorAll('[data-landscape-tool]'))el.onclick=()=>{if(busy)return;tool=el.dataset.landscapeTool;if(['add','subtract'].includes(tool)){showSky=true;recalc();}sync();draw();};
   const locate=e=>{const r=$('#landscape-preview').getBoundingClientRect(),v=view();return{x:clamp((v.x+clamp((e.clientX-r.left)/r.width)*v.width)/w),y:clamp((v.y+clamp((e.clientY-r.top)/r.height)*v.height)/h)};};
   $('#landscape-preview').onpointerdown=e=>{if(e.button!==0||busy)return;const p=locate(e);if(tool==='light'){params.sunX=Math.round(p.x*100);params.sunY=Math.round(p.y*100);autoPending=false;edit('Tâm ánh ấm');return;}if(tool==='pan')pan={clientX:e.clientX,clientY:e.clientY,center:clone(center),view:view()};else if(baseSky)drawing={type:'landscape-sky',add:tool==='add',radius:brush,points:[[p.x,p.y]]};e.currentTarget.setPointerCapture?.(e.pointerId);draw();};
   $('#landscape-preview').onpointermove=e=>{if(pan){const r=e.currentTarget.getBoundingClientRect();center=[pan.center[0]-(e.clientX-pan.clientX)/r.width*pan.view.width/w,pan.center[1]-(e.clientY-pan.clientY)/r.height*pan.view.height/h];draw();}else if(drawing&&drawing.points.length<2000){const p=locate(e);drawing.points.push([p.x,p.y]);draw();}};
   $('#landscape-preview').onpointerup=()=>{if(pan){pan=null;return;}if(!drawing)return;const stroke=drawing;drawing=null;if(strokes.length>=80||strokes.reduce((n,s)=>n+s.points.length,0)+stroke.points.length>20000){note('Đạt giới hạn nét cọ; áp dụng rồi mở lại để chỉnh tiếp.',true);draw();return;}strokes=[...strokes,stroke];autoPending=false;edit('Sửa vùng trời',null,true);};$('#landscape-preview').onpointercancel=()=>{drawing=pan=null;draw();};
   recalc();journal.reset({params:{...params,amount:0},preset,baseSky,strokes:clone(strokes),result:{data:raw,width:w,height:h}});journal.record(snap(),'Phong cảnh một chạm');sync();draw();schedule(0);
  },()=>state.close());return state;
 }
 return{open,cancel,current:()=>active};
}
